namespace sv_bf5371616ca749bda98928dd672ec923.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_bf5371616ca749bda98928dd672ec923.Models;

namespace sv_bf5371616ca749bda98928dd672ec923.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1500); // Simulate network call
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500); // Simulate validation
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@namespace sv_bf5371616ca749bda98928dd672ec923.Components.Pages.ApplySteps

<nav class="step-indicator mb-4" aria-label="Application progress">
    <ol class="d-flex list-unstyled justify-content-between mb-0 p-0">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var isCompleted = stepIndex < CurrentStep;
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <li class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                role="listitem">
                @if (isCompleted)
                {
                    <button class="btn btn-link step-btn p-0 text-decoration-none" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-circle bg-success text-white">&#10003;</span>
                        <span class="step-label d-block mt-1 text-success fw-semibold">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <div class="step-static">
                        <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@(stepIndex + 1)</span>
                        <span class="step-label d-block mt-1 @(isCurrent ? "text-primary fw-semibold" : "text-muted")">@StepNames[stepIndex]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_bf5371616ca749bda98928dd672ec923.Components.Pages.ApplySteps

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
    <input id="fullName" type="text" class="form-control @(Errors.ContainsKey("FullName") ? "is-invalid" : "")"
           @bind="Model.FullName" @bind:event="oninput" />
    @if (Errors.TryGetValue("FullName", out var nameErr))
    {
        <div class="invalid-feedback">@nameErr</div>
    }
</div>

<div class="mb-3">
    <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
    <input id="email" type="email" class="form-control @(Errors.ContainsKey("Email") ? "is-invalid" : "")"
           @bind="Model.Email" @bind:event="oninput" />
    @if (Errors.TryGetValue("Email", out var emailErr))
    {
        <div class="invalid-feedback">@emailErr</div>
    }
</div>

<div class="mb-3">
    <label for="phone" class="form-label">Phone <span class="text-danger">*</span></label>
    <input id="phone" type="tel" class="form-control @(Errors.ContainsKey("Phone") ? "is-invalid" : "")"
           @bind="Model.Phone" @bind:event="oninput" />
    @if (Errors.TryGetValue("Phone", out var phoneErr))
    {
        <div class="invalid-feedback">@phoneErr</div>
    }
</div>

<div class="mb-3">
    <label for="address" class="form-label">Address <span class="text-danger">*</span></label>
    <textarea id="address" class="form-control @(Errors.ContainsKey("Address") ? "is-invalid" : "")"
              rows="2" @bind="Model.Address" @bind:event="oninput"></textarea>
    @if (Errors.TryGetValue("Address", out var addrErr))
    {
        <div class="invalid-feedback">@addrErr</div>
    }
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="OnNext.InvokeAsync" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next &raquo;</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public Dictionary<string, string> Errors { get; set; } = [];
    [Parameter] public bool IsValidating { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }

    public class PersonalInfoModel
    {
        public string FullName { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
        public string Address { get; set; } = "";
    }
}

@namespace sv_bf5371616ca749bda98928dd672ec923.Components.Pages.ApplySteps

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Model.Entries.Count; i++)
{
    var index = i;
    var entry = Model.Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="card-title mb-0">Position @(index + 1)</h6>
                @if (Model.Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control @(GetError(index, "Company") != null ? "is-invalid" : "")"
                           @bind="entry.Company" @bind:event="oninput" />
                    @if (GetError(index, "Company") is { } compErr)
                    {
                        <div class="invalid-feedback">@compErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control @(GetError(index, "Title") != null ? "is-invalid" : "")"
                           @bind="entry.Title" @bind:event="oninput" />
                    @if (GetError(index, "Title") is { } titleErr)
                    {
                        <div class="invalid-feedback">@titleErr</div>
                    }
                </div>
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control @(GetError(index, "StartDate") != null ? "is-invalid" : "")"
                           @bind="entry.StartDate" />
                    @if (GetError(index, "StartDate") is { } startErr)
                    {
                        <div class="invalid-feedback">@startErr</div>
                    }
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="current-@index"
                               @bind="entry.IsCurrent" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
                <div class="col-12">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2" @bind="entry.Description" @bind:event="oninput"></textarea>
                </div>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-primary mb-3" @onclick="AddEntry">
    <span class="me-1">+</span> Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack.InvokeAsync">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next &raquo;</button>
</div>

@code {
    [Parameter, EditorRequired] public WorkHistoryModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public Dictionary<string, string> Errors { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? GetError(int index, string field) =>
        Errors.TryGetValue($"Entries[{index}].{field}", out var err) ? err : null;

    private void AddEntry() => Model.Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index) => Model.Entries.RemoveAt(index);

    public class WorkHistoryModel
    {
        public List<WorkEntryModel> Entries { get; set; } = [new()];
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_bf5371616ca749bda98928dd672ec923.Components.Pages.ApplySteps

<h4 class="mb-3">References</h4>

@for (int i = 0; i < Model.References.Count; i++)
{
    var index = i;
    var reference = Model.References[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="card-title mb-0">Reference @(index + 1)</h6>
                @if (Model.References.Count > 2)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control @(GetError(index, "Name") != null ? "is-invalid" : "")"
                           @bind="reference.Name" @bind:event="oninput" />
                    @if (GetError(index, "Name") is { } nameErr)
                    {
                        <div class="invalid-feedback">@nameErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                    <input type="text" class="form-control @(GetError(index, "Relationship") != null ? "is-invalid" : "")"
                           @bind="reference.Relationship" @bind:event="oninput" />
                    @if (GetError(index, "Relationship") is { } relErr)
                    {
                        <div class="invalid-feedback">@relErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control @(GetError(index, "Email") != null ? "is-invalid" : "")"
                           @bind="reference.Email" @bind:event="oninput" />
                    @if (GetError(index, "Email") is { } emailErr)
                    {
                        <div class="invalid-feedback">@emailErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control @(GetError(index, "Phone") != null ? "is-invalid" : "")"
                           @bind="reference.Phone" @bind:event="oninput" />
                    @if (GetError(index, "Phone") is { } phoneErr)
                    {
                        <div class="invalid-feedback">@phoneErr</div>
                    }
                </div>
            </div>
        </div>
    </div>
}

@if (Model.References.Count < MaxReferences)
{
    <button class="btn btn-outline-primary mb-3" @onclick="AddReference">
        <span class="me-1">+</span> Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack.InvokeAsync">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next &raquo;</button>
</div>

@code {
    private const int MaxReferences = 3;

    [Parameter, EditorRequired] public ReferencesModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public Dictionary<string, string> Errors { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? GetError(int index, string field) =>
        Errors.TryGetValue($"References[{index}].{field}", out var err) ? err : null;

    private void AddReference()
    {
        if (Model.References.Count < MaxReferences)
            Model.References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index) => Model.References.RemoveAt(index);

    public class ReferencesModel
    {
        public List<ReferenceModel> References { get; set; } = [new(), new()];
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_bf5371616ca749bda98928dd672ec923.Components.Pages.ApplySteps

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-3">
    <label for="coverLetter" class="form-label">Write your cover letter below <span class="text-danger">*</span></label>
    <textarea id="coverLetter" class="form-control @(Errors.ContainsKey("CoverLetter") ? "is-invalid" : "")"
              rows="12" maxlength="@MaxLength"
              @bind="Model.CoverLetter" @bind:event="oninput"></textarea>
    @if (Errors.TryGetValue("CoverLetter", out var err))
    {
        <div class="invalid-feedback">@err</div>
    }
    <div class="form-text text-end">
        @Model.CoverLetter.Length / @MaxLength characters
    </div>
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack.InvokeAsync">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next &raquo;</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public CoverLetterModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public Dictionary<string, string> Errors { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    public class CoverLetterModel
    {
        public string CoverLetter { get; set; } = "";
    }
}

@namespace sv_bf5371616ca749bda98928dd672ec923.Components.Pages.ApplySteps

<h4 class="mb-3">Review &amp; Submit</h4>

@if (IsSubmitted)
{
    <div class="alert alert-success text-center p-4">
        <h5 class="alert-heading">Application Submitted Successfully!</h5>
        <p class="mb-0">Your application ID is <strong>#@ApplicationId</strong>. Please save this for your records.</p>
    </div>
}
else
{
    <!-- Personal Info -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6"><strong>Name:</strong> @Personal.FullName</div>
                <div class="col-md-6"><strong>Email:</strong> @Personal.Email</div>
                <div class="col-md-6"><strong>Phone:</strong> @Personal.Phone</div>
                <div class="col-md-6"><strong>Address:</strong> @Personal.Address</div>
            </div>
        </div>
    </div>

    <!-- Work History -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in WorkHistory.Entries)
            {
                <div class="mb-3 pb-2 border-bottom">
                    <div><strong>@entry.Title</strong> at @entry.Company</div>
                    <div class="text-muted small">
                        @entry.StartDate?.ToString("MMM yyyy") &ndash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <div class="mt-1">@entry.Description</div>
                    }
                </div>
            }
        </div>
    </div>

    <!-- References -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var reference in References.References)
            {
                <div class="mb-2">
                    <strong>@reference.Name</strong> (@reference.Relationship)<br />
                    <span class="text-muted">@reference.Email &middot; @reference.Phone</span>
                </div>
            }
        </div>
    </div>

    <!-- Cover Letter -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Cover Letter</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <div class="card-body">
            <p style="white-space: pre-wrap;">@CoverLetter.CoverLetter</p>
        </div>
    </div>

    @if (!string.IsNullOrEmpty(SubmitError))
    {
        <div class="alert alert-danger">@SubmitError</div>
    }

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack.InvokeAsync">&laquo; Back</button>
        <button class="btn btn-success btn-lg" @onclick="OnSubmit.InvokeAsync" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                <span>Submitting…</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
}

@code {
