@namespace sv_bf5371616ca749bda98928dd672ec923.Components.Pages.ApplySteps

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Model.Entries.Count; i++)
{
    var index = i;
    var entry = Model.Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="card-title mb-0">Position @(index + 1)</h6>
                @if (Model.Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control @(GetError(index, "Company") != null ? "is-invalid" : "")"
                           @bind="entry.Company" @bind:event="oninput" />
                    @if (GetError(index, "Company") is { } compErr)
                    {
                        <div class="invalid-feedback">@compErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control @(GetError(index, "Title") != null ? "is-invalid" : "")"
                           @bind="entry.Title" @bind:event="oninput" />
                    @if (GetError(index, "Title") is { } titleErr)
                    {
                        <div class="invalid-feedback">@titleErr</div>
                    }
                </div>
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control @(GetError(index, "StartDate") != null ? "is-invalid" : "")"
                           @bind="entry.StartDate" />
                    @if (GetError(index, "StartDate") is { } startErr)
                    {
                        <div class="invalid-feedback">@startErr</div>
                    }
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="current-@index"
                               @bind="entry.IsCurrent" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
                <div class="col-12">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2" @bind="entry.Description" @bind:event="oninput"></textarea>
                </div>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-primary mb-3" @onclick="AddEntry">
    <span class="me-1">+</span> Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack.InvokeAsync">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next &raquo;</button>
</div>

@code {
    [Parameter, EditorRequired] public WorkHistoryModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public Dictionary<string, string> Errors { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? GetError(int index, string field) =>
        Errors.TryGetValue($"Entries[{index}].{field}", out var err) ? err : null;

    private void AddEntry() => Model.Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index) => Model.Entries.RemoveAt(index);

    public class WorkHistoryModel
    {
        public List<WorkEntryModel> Entries { get; set; } = [new()];
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_bf5371616ca749bda98928dd672ec923.Components.Pages.ApplySteps

<h4 class="mb-3">References</h4>

@for (int i = 0; i < Model.References.Count; i++)
{
    var index = i;
    var reference = Model.References[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="card-title mb-0">Reference @(index + 1)</h6>
                @if (Model.References.Count > 2)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control @(GetError(index, "Name") != null ? "is-invalid" : "")"
                           @bind="reference.Name" @bind:event="oninput" />
                    @if (GetError(index, "Name") is { } nameErr)
                    {
                        <div class="invalid-feedback">@nameErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                    <input type="text" class="form-control @(GetError(index, "Relationship") != null ? "is-invalid" : "")"
                           @bind="reference.Relationship" @bind:event="oninput" />
                    @if (GetError(index, "Relationship") is { } relErr)
                    {
                        <div class="invalid-feedback">@relErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control @(GetError(index, "Email") != null ? "is-invalid" : "")"
                           @bind="reference.Email" @bind:event="oninput" />
                    @if (GetError(index, "Email") is { } emailErr)
                    {
                        <div class="invalid-feedback">@emailErr</div>
                    }
                </div>
                <div class="col-md-6">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control @(GetError(index, "Phone") != null ? "is-invalid" : "")"
                           @bind="reference.Phone" @bind:event="oninput" />
                    @if (GetError(index, "Phone") is { } phoneErr)
                    {
                        <div class="invalid-feedback">@phoneErr</div>
                    }
                </div>
            </div>
        </div>
    </div>
}

@if (Model.References.Count < MaxReferences)
{
    <button class="btn btn-outline-primary mb-3" @onclick="AddReference">
        <span class="me-1">+</span> Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack.InvokeAsync">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next &raquo;</button>
</div>

@code {
    private const int MaxReferences = 3;

    [Parameter, EditorRequired] public ReferencesModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public Dictionary<string, string> Errors { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? GetError(int index, string field) =>
        Errors.TryGetValue($"References[{index}].{field}", out var err) ? err : null;

    private void AddReference()
    {
        if (Model.References.Count < MaxReferences)
            Model.References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index) => Model.References.RemoveAt(index);

    public class ReferencesModel
    {
        public List<ReferenceModel> References { get; set; } = [new(), new()];
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

