+            <ReferencesStep Model="_references" Errors="_errors"
+                            OnNext="NextFromReferences" OnBack="Back" />
+            break;
+        case 3:
+            <CoverLetterStep Model="_coverLetter" Errors="_errors"
+                             OnNext="NextFromCoverLetter" OnBack="Back" />
+            break;
+        case 4:
+            <ReviewStep Personal="_personalInfo" WorkHistory="_workHistory"
+                        References="_references" CoverLetter="_coverLetter"
+                        IsSubmitting="_isSubmitting" IsSubmitted="_isSubmitted"
+                        ApplicationId="_applicationId" SubmitError="_submitError"
+                        OnBack="Back" OnSubmit="Submit" OnEditStep="GoToStep" />
+            break;
+    }
+</div>
+
+@code {
+    private int _currentStep;
+    private bool _isValidatingEmail;
+    private bool _isSubmitting;
+    private bool _isSubmitted;
+    private int? _applicationId;
+    private string? _submitError;
+    private Dictionary<string, string> _errors = [];
+
+    private readonly List<string> _stepNames =
+    [
+        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
+    ];
+
+    private readonly PersonalInfoStep.PersonalInfoModel _personalInfo = new();
+    private readonly WorkHistoryStep.WorkHistoryModel _workHistory = new();
+    private readonly ReferencesStep.ReferencesModel _references = new();
+    private readonly CoverLetterStep.CoverLetterModel _coverLetter = new();
+
+    private void GoToStep(int step)
+    {
+        if (step < _currentStep)
+        {
+            _errors.Clear();
+            _currentStep = step;
+        }
+    }
+
+    private void Back()
+    {
+        _errors.Clear();
+        if (_currentStep > 0)
+            _currentStep--;
+    }
+
+    // --- Step 1: Personal Info ---
+    private async Task NextFromPersonalInfo()
+    {
+        _errors.Clear();
+
+        if (string.IsNullOrWhiteSpace(_personalInfo.FullName))
+            _errors["FullName"] = "Full name is required.";
+        if (string.IsNullOrWhiteSpace(_personalInfo.Email))
+            _errors["Email"] = "Email is required.";
+        if (string.IsNullOrWhiteSpace(_personalInfo.Phone))
+            _errors["Phone"] = "Phone is required.";
+        if (string.IsNullOrWhiteSpace(_personalInfo.Address))
+            _errors["Address"] = "Address is required.";
+
+        if (_errors.Count > 0) return;
+
+        _isValidatingEmail = true;
+        StateHasChanged();
+
+        try
+        {
+            var emailValid = await ApplicationService.ValidateEmailAsync(_personalInfo.Email);
+            if (!emailValid)
+            {
+                _errors["Email"] = "Please enter a valid email address.";
+                return;
+            }
+        }
+        finally
+        {
+            _isValidatingEmail = false;
+        }
+
+        _currentStep = 1;
+    }
+
+    // --- Step 2: Work History ---
+    private void NextFromWorkHistory()
+    {
+        _errors.Clear();
+
+        for (int i = 0; i < _workHistory.Entries.Count; i++)
+        {
+            var entry = _workHistory.Entries[i];
+            if (string.IsNullOrWhiteSpace(entry.Company))
+                _errors[$"Entries[{i}].Company"] = "Company name is required.";
+            if (string.IsNullOrWhiteSpace(entry.Title))
+                _errors[$"Entries[{i}].Title"] = "Job title is required.";
+            if (entry.StartDate is null)
+                _errors[$"Entries[{i}].StartDate"] = "Start date is required.";
+        }
+
+        if (_errors.Count == 0)
+            _currentStep = 2;
+    }
+
+    // --- Step 3: References ---
+    private void NextFromReferences()
+    {
+        _errors.Clear();
+
+        for (int i = 0; i < _references.References.Count; i++)
+        {
+            var r = _references.References[i];
+            if (string.IsNullOrWhiteSpace(r.Name))
+                _errors[$"References[{i}].Name"] = "Name is required.";
+            if (string.IsNullOrWhiteSpace(r.Relationship))
+                _errors[$"References[{i}].Relationship"] = "Relationship is required.";
+            if (string.IsNullOrWhiteSpace(r.Email))
+                _errors[$"References[{i}].Email"] = "Email is required.";
+            if (string.IsNullOrWhiteSpace(r.Phone))
+                _errors[$"References[{i}].Phone"] = "Phone is required.";
+        }
+
+        if (_errors.Count == 0)
+            _currentStep = 3;
+    }
+
+    // --- Step 4: Cover Letter ---
+    private void NextFromCoverLetter()
+    {
+        _errors.Clear();
+
+        if (string.IsNullOrWhiteSpace(_coverLetter.CoverLetter))
+            _errors["CoverLetter"] = "Cover letter is required.";
+
+        if (_errors.Count == 0)
+            _currentStep = 4;
+    }
+
+    // --- Step 5: Submit ---
+    private async Task Submit()
+    {
+        _isSubmitting = true;
+        _submitError = null;
+        StateHasChanged();
+
+        try
+        {
+            var application = new JobApplication(
+                new PersonalInfo(_personalInfo.FullName, _personalInfo.Email, _personalInfo.Phone, _personalInfo.Address),
+                new WorkHistory(_workHistory.Entries.Select(e =>
+                    new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue,
+                        e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
+                _references.References.Select(r =>
+                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+                _coverLetter.CoverLetter
+            );
+
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            _isSubmitted = true;
+        }
+        catch (Exception ex)
+        {
+            _submitError = $"Submission failed: {ex.Message}. Please try again.";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+}
+

